excels.excel:

EXPORT WITH SHEET="产品季度销量", HEADER=true,
    MAPPING={"a":"产品","b":"一季度","c":"二季度","d":"三季度","e":"四季度","f":"全年"},
    FORMAT={"b":"#,##0","c":"#,##0","d":"#,##0","e":"#,##0","f":"#,##0"},
    FORMULAS={
        F2:'SUM(B2:E2)',F3:'SUM(B3:E3)',F4:'SUM(B4:E4)',F5:'SUM(B5:E5)',
        B6:'SUM(B2:B5)',C6:'SUM(C2:C5)',D6:'SUM(D2:D5)',E6:'SUM(E2:E5)',F6:'SUM(F2:F5)'
    },
    STYLE={ROW 6:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center}},
    GRAPH={TYPE=COLUMN, TITLE="产品季度销量图", CATEGORY_AXIS=产品, VALUE_AXIS=销量,
           CATEGORIES=["产品A","产品B","产品C","产品D"],
           SERIES=[
               {NAME=一季度, DATA=[120,200,150,180]},
               {NAME=二季度, DATA=[180,210,190,160]},
               {NAME=三季度, DATA=[150,220,170,200]},
               {NAME=四季度, DATA=[200,240,210,190]}
           ]}
